const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define region covering East Midlands, northeast England, and eastern Scotland
  const region = ee.Geometry.Polygon([
    [[-3.5, 55.5], [-0.5, 55.5], [-0.5, 53.0], [-3.5, 53.0], [-3.5, 55.5]]
  ]);

  // Recent period: Oct 1, 2023 to Jan 4, 2024
  const recentStart = '2023-10-01';
  const recentEnd = '2024-01-05'; // Exclusive end date

  // Baseline period: 1991-2020 averages for same months
  const baselineStart = '1991-10-01';
  const baselineEnd = '2020-01-05';

  // Get CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // Recent period collection
  const recentCol = chirps
    .filterDate(recentStart, recentEnd)
    .filterBounds(region);

  // Baseline period collection (multiple years)
  const baselineCol = chirps
    .filterDate(baselineStart, baselineEnd)
    .filterBounds(region);

  // Check data availability
  const recentCount = recentCol.size().getInfo();
  const baselineCount = baselineCol.size().getInfo();

  console.log(`Recent period images: ${recentCount}`);
  console.log(`Baseline period images: ${baselineCount}`);

  if (recentCount === 0 || baselineCount === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate total precipitation for recent period
  const recentTotal = recentCol.sum();

  // Calculate average precipitation for baseline period
  const baselineMean = baselineCol.mean();

  // Get valid pixel counts
  const recentStats = recentTotal.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  });

  const baselineStats = baselineMean.reduceRegion({
    reducer: ee.Reducer.count(), 
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  });

  const recentPixels = recentStats.get('precipitation').getInfo();
  const baselinePixels = baselineStats.get('precipitation').getInfo();

  console.log(`Recent valid pixels: ${recentPixels}`);
  console.log(`Baseline valid pixels: ${baselinePixels}`);

  if (recentPixels === 0 || baselinePixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate mean precipitation values
  const recentMean = recentTotal.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const baselineMeanVal = baselineMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000, 
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Recent mean precip: ${recentMean?.toFixed(2)} mm`);
  console.log(`Baseline mean precip: ${baselineMeanVal?.toFixed(2)} mm`);

  // Validate results
  if (recentMean === null || baselineMeanVal === null || 
      isNaN(recentMean) || isNaN(baselineMeanVal) ||
      recentMean < 0 || baselineMeanVal < 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare recent vs baseline
  if (recentMean > baselineMeanVal) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
